[asy]import graph;
size(125,72.5);
picture p;
draw(p,unitsquare);
filldraw(p,Circle((.5,.5),.3),white);
label(p,"Enter",(.5,.5),ZapfChancery("m","n"));
add(p);
filldraw(Circle((2,.5),.4),gray(.6));
add(shift(1.5*right)*p);
draw((1.1,.5)--(1.4,.5),EndArrow(5,25));[/asy]

