import Mathlib

def dot (u v : ℝ × ℝ) : ℝ := u.1 * v.1 + u.2 * v.2
def mul_left (u : ℝ) (v : ℝ × ℝ) : ℝ × ℝ := (u * v.1, u * v.2)
def mul_right (u : ℝ × ℝ) (v : ℝ) : ℝ × ℝ := (u.1 * v, u.2 * v)

