theorem algebra_20931 {A B C : ℤ} (h : ∀ x : ℝ, x ≠ -2 → (x + A) / (B * x + C) = (-x + 4) / (x - 2)) (h1 : B * (4 : ℝ) + C ≠ 0) (h2 : (C : ℝ) ≠ 0) (h3 : B * (3 : ℝ) + C ≠ 0) :
    A + B + C = -3 := by

